import Foundation

enum SeedVibes {
    struct Entry: Decodable, Sendable {
        let vibe: String
        let tags: [String]
        let howUsed: String
    }

    // The JSON is generated by scripts/gen-seed.sh, which validates it, and a test decodes it.
    static let all: [String: Entry] = try! JSONDecoder().decode([String: Entry].self, from: Data(seedVibesJSON.utf8))
}
